 void detectMedia(){if(browser==null||browser.getUrl()==null)return;String current=browser.getUrl();if(!prefs.getBoolean("js",true)){analyze(current);return;}browser.evaluateJavascript("(function(){let out=[];for(let e of document.querySelectorAll('video,audio')){if(e.mediaKeys)continue;for(let u of [e.currentSrc,e.src,...Array.from(e.querySelectorAll('source')).map(s=>s.src)])if(u&&/^https?:/.test(u))out.push(u)}for(let a of document.querySelectorAll('a[download]'))if(a.href&&/^https?:/.test(a.href))out.push(a.href);return [...new Set(out)].slice(0,20)})()",raw->{if(closed||screen!=1)return;ArrayList<String> links=new ArrayList<>();links.add(current);try{JSONArray arr=new JSONArray(raw);for(int i=0;i<arr.length();i++){String u=arr.getString(i);if(allowed(u)&&!links.contains(u))links.add(u);}}catch(Exception ignored){}if(links.size()==1){analyze(current);return;}String[] labels=new String[links.size()];labels[0]=tr("تحليل الصفحة والجودات","Analyze page & formats");for(int i=1;i<links.size();i++){Uri u=Uri.parse(links.get(i));String name=u.getLastPathSegment();labels[i]=(name==null?"Media":name)+" · "+u.getHost();}new AlertDialog.Builder(this).setTitle(tr("الوسائط المتاحة","Available media")).setItems(labels,(d,w)->analyze(links.get(w))).setNegativeButton("Cancel",null).show();});}
